    public class ExchangeRateClient {
        public class ExchangeRateException extends Exception {}

        public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
            // 1. Normalise
            String normalizedBase = (baseCurrency != null) ? baseCurrency.trim().toUpperCase() : '';
            Set<String> normalizedQuotes = new Set<String>();
            if (quoteCurrencies != null) {
                for (String q : quoteCurrencies) {
                    if (q != null) {
                        normalizedQuotes.add(q.trim().toUpperCase());
                    }
                }
            }

            // 2. Validate
            if (!isValidCurrency(normalizedBase) || normalizedQuotes.isEmpty()) {
                throw new ExchangeRateException('Invalid base currency or empty quotes');
            }
            for (String q : normalizedQuotes) {
                if (!isValidCurrency(q)) {
                    throw new ExchangeRateException('Invalid quote currency: ' + q);
                }
            }

            // 3. Prepare Request
            String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base=' + normalizedBase + '&symbols=' + String.join(new List<String>(normalizedQuotes), ',');
            Http http = new Http();
            HttpRequest req = new HttpRequest();
            req.setEndpoint(endpoint);
            req.setMethod('GET');
            req.setHeader('Accept', 'application/json');

            // 4. Execute Callout with Retry
            HttpResponse res = http.send(req);
            if (res.getStatusCode() == 503) {
                res = http.send(req);
            }

            // 5. Check Status
            if (res.getStatusCode() != 200) {
                throw new ExchangeRateException('Error: ' + res.getStatusCode());
            }

            // 6. Parse Body
