                    result.put(q, Decimal.valueOf(String.valueOf(rateVal)));
                }
                return result;

            } catch (Exception e) {
                if (e instanceof ExchangeRateException) throw e;
                throw new ExchangeRateException('Failed to parse response: ' + e.getMessage());
