public class CaseSurveyJob implements Queueable {
    private final Id caseId;

    /**
     * @param caseId The ID of the Case for which the survey task should be created.
     */
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    /**
     * Executes the job to create a Task for the customer survey.
     * @param context The queueable context.
     */
    public void execute(QueueableContext context) {
        // Query the necessary fields for Task creation.
        // We query the ContactId here to ensure data integrity in the async context.
        Case c = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :caseId LIMIT 1];

        if (c.ContactId != null) {
            Task surveyTask = new Task(
                WhatId = c.Id,
